{
  "name": "Pfeiffer TPG 300 真空规",
  "name_en": "Pfeiffer TPG 300 Vacuum Gauge",
  "manufacturer": "Pfeiffer",
  "description": "用于测量实验真空系统压力的真空规。根据代码证据，该设备通过 Arduino 的 ADC 采集接口读取测量信号并返回真空测量值，适合用于真空状态监测。",
  "description_en": "A vacuum gauge used to measure pressure in laboratory vacuum systems. Based on the driver evidence, its signal is read through an Arduino ADC interface and returned as measurement values for vacuum monitoring.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到 Arduino 采集接口。",
      "description_en": "Connect to the Arduino readout interface."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与 Arduino 采集接口的连接。",
      "description_en": "Disconnect from the Arduino readout interface."
    },
    {
      "action_name": "auto-rcv_vals",
      "description": "接收并返回真空测量值。",
      "description_en": "Receive and return vacuum measurement values."
    }
  ],
  "tag_hints": [
    "vacuum measurement",
    "Pfeiffer TPG 300",
    "vacuum gauge",
    "pressure sensing",
    "Arduino ADC readout",
    "vacuum monitoring"
  ]
}

